#include <algorithm>
#include <fstream>
int main() {
    std::ifstream in("paint.in");
    std::ofstream out("paint.out");
    int a, b, c, d;
    in >> a >> b >> c >> d;
    int overlap = std::max(0, std::min(b, d) - std::max(a, c));
    out << (b - a) + (d - c) - overlap << '\n';
}
