#include <algorithm>
#include <array>
#include <fstream>
int main() {
    std::ifstream in("speeding.in");
    std::ofstream out("speeding.out");
    int n, m;
    in >> n >> m;
    std::array<int, 100> limit{}, speed{};
    int pos = 0;
    for (int i = 0; i < n; ++i) {
        int len, value;
        in >> len >> value;
        for (int k = 0; k < len; ++k) limit[pos++] = value;
    }
    pos = 0;
    for (int i = 0; i < m; ++i) {
        int len, value;
        in >> len >> value;
        for (int k = 0; k < len; ++k) speed[pos++] = value;
    }
    int answer = 0;
    for (int i = 0; i < 100; ++i) answer = std::max(answer, speed[i] - limit[i]);
    out << answer << '\n';
}
