#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("badmilk.in");
    std::ofstream out("badmilk.out");
    int n, m, d, s;
    in >> n >> m >> d >> s;
    const int never = 101;
    std::vector<std::vector<int>> earliest(n + 1, std::vector<int>(m + 1, never));
    for (int i = 0; i < d; ++i) {
        int p, milk, time;
        in >> p >> milk >> time;
        earliest[p][milk] = std::min(earliest[p][milk], time);
    }
    std::vector<std::pair<int, int>> sick(s);
    for (auto& observation : sick) in >> observation.first >> observation.second;
    int answer = 0;
    for (int milk = 1; milk <= m; ++milk) {
        bool possible = true;
        for (const auto& observation : sick) {
            if (earliest[observation.first][milk] >= observation.second) possible = false;
        }
        if (!possible) continue;
        int consumers = 0;
        for (int p = 1; p <= n; ++p) if (earliest[p][milk] != never) ++consumers;
        answer = std::max(answer, consumers);
    }
    out << answer << '\n';
}
